const listVisibleFbTopics = `-- name: ListVisibleFbTopics :many

SELECT t.id, t.project_id, t.title, t.body, t.answer_hint, t.status, t.visibility, t.pinned, t.answer_count, t.ends_at, t.published_at, t.created_by, t.created_at, t.updated_at, p.name AS project_name, p.slug AS project_slug, p.cover AS project_cover
FROM fb_topic t
JOIN fb_project p ON p.id = t.project_id
LEFT JOIN fb_project_member m ON m.project_id = p.id AND m.user_id = $1::bigint AND m.status = 'active'
WHERE t.status IN ('open', 'closed')
  AND p.status <> 'draft'
  AND (p.visibility = 'public' OR m.user_id IS NOT NULL)
  AND (t.visibility = 'public' OR m.user_id IS NOT NULL)
  AND ($2::bigint IS NULL OR t.project_id = $2)
  AND ($3::text IS NULL OR t.status = $3)
ORDER BY (t.status = 'open') DESC, t.pinned DESC, t.published_at DESC, t.id DESC
LIMIT $5 OFFSET $4
`

